const items = $input.all();

return items.map((item) => {
  const data = item.json;

  const contactName = data["Contact Name"] || "there";
  const email = data["Email"] || "";
  const company = data["Company"] || "";
  const previousTopic =
    data["Previous Topic"] || "improving your lead follow-up process";
  const followUpNumber = Number(data["Follow-up Number"] || 0);

  const subject =
    followUpNumber >= 2
      ? `Quick follow-up regarding ${previousTopic}`
      : `Following up regarding ${previousTopic}`;

  const body = `Hi ${contactName},

I wanted to follow up on my previous note regarding ${previousTopic}.

If improving this process is still a priority for ${company}, I would be happy to show you a quick demonstration of how an AI automation workflow can capture, qualify, and follow up with leads automatically.

Would you be available for a brief conversation this week?

Best,
Alex
ABM Solutions`;

  const htmlBody = `
<p>Hi ${contactName},</p>

<p>I wanted to follow up on my previous note regarding ${previousTopic}.</p>

<p>If improving this process is still a priority for ${company}, I would be happy to show you a quick demonstration of how an AI automation workflow can capture, qualify, and follow up with leads automatically.</p>

<p>Would you be available for a brief conversation this week?</p>

<p>Best,<br>
Alex<br>
ABM Solutions</p>
`;

  return {
    json: {
      ...data,
      to: email,
      subject,
      body,
      htmlBody,
      followUpAt: new Date().toISOString(),
      status: "FOLLOW_UP_COPY_READY",
    },
  };
});

const sentEmails = $input.all();
const originalRecords = $items("Create Follow-up Copy");

return sentEmails.map((sentEmail, index) => {
  const original = originalRecords[index]?.json || {};

  const currentCount = Number(original["Follow-up Number"] || 0);
  const updatedCount = currentCount + 1;

  return {
    json: {
      ...original,
      "Follow-up Number": updatedCount,
      "Last Follow-up Date": new Date().toISOString(),
      "Status": updatedCount >= 3 ? "Completed" : "Open",
      gmailMessageId: sentEmail.json.id || "",
      gmailThreadId: sentEmail.json.threadId || "",
      crmUpdateStatus: "FOLLOW_UP_LOGGED",
      nextRecommendedStep:
        updatedCount >= 3
          ? "Move to nurture sequence or stop follow-up."
          : "Schedule the next follow-up."
    }
  };
});
